class Solution { public int secondMinimum(int n,int[][] e,int time,int change) { List<Integer>[] g=new List[n+1];for(int i=1;i<=n;i++)g[i]=new ArrayList<>();for(int[] x:e){g[x[0]].add(x[1]);g[x[1]].add(x[0]);}int[] a=new int[n+1],b=new int[n+1];Arrays.fill(a,-1);Arrays.fill(b,-1);ArrayDeque<int[]>q=new ArrayDeque<>();a[1]=0;q.add(new int[]{1,0});int steps=-1;while(!q.isEmpty()&&steps<0){int[] z=q.remove();for(int v:g[z[0]]){int d=z[1]+1;if(a[v]<0){a[v]=d;q.add(new int[]{v,d});}else if(b[v]<0&&d>a[v]){b[v]=d;if(v==n){steps=d;break;}q.add(new int[]{v,d});}}}int cur=0;for(int i=0;i<steps;i++){if((cur/change)%2==1)cur=((cur/change)+1)*change;cur+=time;}return cur;} }
